SELECT id, source, source_day, notice_id, unp, contract_number, lot_no, buyer_eik, coalesce(m.display, t.supplier_display), awarded_to_group, subject, tender_name, procedure_type, cpv, cpv_description, contract_type, contract_date, published_at, effective_date, date_basis, value_initial, value_current, value_current_currency, currency, fx_rate, value_initial_eur, value_current_eur, amount_eur, value_flag, date_flag, estimated_value, estimate_currency, estimated_eur, estimate_ratio, offers_count, sme_offers_count, disqualified_offers_count, is_eu_funded, european_program, is_framework, framework_contract, linked_tenders, direct_award_justification, award_method, legal_basis, has_subcontractors, supplier_nuts, supplier_size, contract_period_days, annex_count FROM tender.contract t
LEFT JOIN (SELECT s.contract_id, string_agg(CASE WHEN u.party_key IS NULL THEN s.name ELSE 'Без ЕИК и правна форма' END, '; ' ORDER BY s."position") display
           FROM tender.contract_supplier s LEFT JOIN tender.unnamed_party u USING (party_key)
           WHERE s.contract_id IN (SELECT x.contract_id FROM tender.contract_supplier x JOIN tender.unnamed_party y USING (party_key))
           GROUP BY 1) m ON m.contract_id = t.id
